const metaIconFor = (type, cls) => {
    if (type === "pdf") return <Icon.pdf className={cls} />;
      if (type === "note") return <Icon.note className={cls} />;
        if (type === "book") return <Icon.book className={cls} />;
          return null;
          };

function Toggle({ checked, onChange }) {
    return (
        <button
              type="button"
                    onClick={() => onChange(!checked)}
                          className="relative inline-flex h-6 w-11 items-center rounded-full transition-colors shrink-0"
                                style={{ backgroundColor: checked ? "#1E3A8A" : "#D1D5DB" }}
                                      aria-pressed={checked}
                                          >
                                                <span
                                                        className="inline-block h-4.5 w-4.5 transform rounded-full bg-white shadow transition-transform"
                                                                style={{
                                                                          height: 18,
                                                                                    width: 18,
                                                                                              transform: checked ? "translateX(-22px)" : "translateX(-2px)",
                                                                                                      }}
                                                                                                            />
                                                                                                                </button>
                                                                                                                  );
                                                                                                                  }

function PriorityDot({ id }) {
    const m = priorityMeta(id);
      return <span className="inline-block w-2 h-2 rounded-full" style={{ backgroundColor: m.color }} />;
      }
